def tune_pid_parameters():
    """
    Tune PID parameters using grid search.

    Returns:
        dict: Best parameters
    """
    print("Starting PID parameter tuning...")

    # Define search space (constrained ranges)
    # Speed control: kp in (0,10), ki in [0,5), kd in [0,5)
    kp_speed_values = [0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 4.0, 5.0]
    ki_speed_values = [0.0, 0.05, 0.1, 0.15, 0.2, 0.3, 0.5]
    kd_speed_values = [0.0, 0.2, 0.5, 0.8, 1.0, 1.5, 2.0]

    # Distance control: kp in (0,10), ki in [0,5), kd in [0,5)
    kp_dist_values = [0.2, 0.5, 0.8, 1.0, 1.5, 2.0, 3.0]
    ki_dist_values = [0.0, 0.02, 0.05, 0.1, 0.15, 0.2]
    kd_dist_values = [0.0, 0.5, 1.0, 1.5, 2.0, 3.0]

    best_score = float('inf')
    best_params = None
    iteration = 0

    # Coarse grid search first
    for kp_s in kp_speed_values[::2]:  # Sample every other value
        for ki_s in ki_speed_values[::2]:
            for kd_s in kd_speed_values[::2]:
                for kp_d in kp_dist_values[::2]:
                    for ki_d in ki_dist_values[::2]:
                        for kd_d in kd_dist_values[::2]:
                            iteration += 1

                            # Run simulation
                            results_df = simulate_with_params(
                                kp_s, ki_s, kd_s, kp_d, ki_d, kd_d
                            )

                            # Calculate metrics
                            metrics = calculate_metrics(results_df)
                            score = calculate_score(metrics)

                            if score < best_score:
                                best_score = score
                                best_params = {
                                    'pid_speed': {'kp': kp_s, 'ki': ki_s, 'kd': kd_s},
                                    'pid_distance': {'kp': kp_d, 'ki': ki_d, 'kd': kd_d}
                                }
                                print(f"Iteration {iteration}: New best score = {score:.2f}")
                                print(f"  Speed PID: Kp={kp_s}, Ki={ki_s}, Kd={kd_s}")
                                print(f"  Dist PID:  Kp={kp_d}, Ki={ki_d}, Kd={kd_d}")
                                print(f"  Metrics: {metrics}")

    # Fine-tune around best parameters
    print("\nFine-tuning around best parameters...")
    base_kp_s = best_params['pid_speed']['kp']
    base_ki_s = best_params['pid_speed']['ki']
    base_kd_s = best_params['pid_speed']['kd']
    base_kp_d = best_params['pid_distance']['kp']
    base_ki_d = best_params['pid_distance']['ki']
    base_kd_d = best_params['pid_distance']['kd']

    # Fine search around best values
    for kp_s in [base_kp_s - 0.2, base_kp_s, base_kp_s + 0.2]:
        for ki_s in [max(0, base_ki_s - 0.05), base_ki_s, base_ki_s + 0.05]:
            for kd_s in [max(0, base_kd_s - 0.2), base_kd_s, base_kd_s + 0.2]:
                for kp_d in [base_kp_d - 0.2, base_kp_d, base_kp_d + 0.2]:
                    for ki_d in [max(0, base_ki_d - 0.02), base_ki_d, base_ki_d + 0.02]:
                        for kd_d in [max(0, base_kd_d - 0.2), base_kd_d, base_kd_d + 0.2]:
                            # Validate constraints
                            if kp_s <= 0 or kp_s >= 10:
                                continue
                            if ki_s < 0 or ki_s >= 5:
                                continue
                            if kd_s < 0 or kd_s >= 5:
                                continue
                            if kp_d <= 0 or kp_d >= 10:
                                continue
                            if ki_d < 0 or ki_d >= 5:
                                continue
                            if kd_d < 0 or kd_d >= 5:
                                continue

                            iteration += 1

                            results_df = simulate_with_params(
                                kp_s, ki_s, kd_s, kp_d, ki_d, kd_d
                            )

                            metrics = calculate_metrics(results_df)
                            score = calculate_score(metrics)

                            if score < best_score:
                                best_score = score
                                best_params = {
                                    'pid_speed': {'kp': kp_s, 'ki': ki_s, 'kd': kd_s},
                                    'pid_distance': {'kp': kp_d, 'ki': ki_d, 'kd': kd_d}
                                }
                                print(f"Iteration {iteration}: New best score = {score:.2f}")
                                print(f"  Speed PID: Kp={kp_s:.2f}, Ki={ki_s:.3f}, Kd={kd_s:.2f}")
                                print(f"  Dist PID:  Kp={kp_d:.2f}, Ki={ki_d:.3f}, Kd={kd_d:.2f}")

    print(f"\nTuning completed after {iteration} iterations")
    print(f"Best score: {best_score:.2f}")
    print(f"Best parameters: {best_params}")

    return best_params

